-- Finance ledger: encrypted income/expense entries and tags (ADR-0015,
-- docs/plans/finance-phase-2-ledger.md).
--
-- Replaces the plaintext expenses and income tables, which held seed data
-- only. Each row keeps the columns SQL must filter on in plaintext (kind,
-- car, date, showroom) and everything else (amount, purpose, tag ids, party,
-- note; tag name and colour) in one AES-256-GCM `payload` sealed with the
-- vault's data key and bound to the row id. Ids are generated by the backend
-- because the seal needs them before the insert.
--
-- Both tables are reached only by the backend's service role: RLS on, no
-- policies.

drop table public.expenses;
drop table public.income;

create table public.finance_entries (
  id uuid primary key,
  showroom_id uuid not null references public.showrooms (id),
  kind text not null,
  vehicle_id uuid references public.vehicles (id),
  entry_date date not null,
  payload text not null,
  key_version integer not null,
  recorded_by uuid not null references public.users (id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  constraint finance_entries_kind_check check (kind in ('income', 'expense'))
);

create index finance_entries_showroom_date_idx
  on public.finance_entries (showroom_id, entry_date)
  where deleted_at is null;

create index finance_entries_vehicle_idx
  on public.finance_entries (vehicle_id)
  where deleted_at is null;

create index finance_entries_date_idx
  on public.finance_entries (entry_date)
  where deleted_at is null;

alter table public.finance_entries enable row level security;

create table public.finance_tags (
  id uuid primary key,
  payload text not null,
  key_version integer not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  archived_at timestamptz
);

alter table public.finance_tags enable row level security;
